from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def apply_percentage(amount: Decimal, percent: Decimal) -> Decimal:
    """Reduces amount by percent, rounded to the cent."""
    return (amount * (Decimal(100) - percent) / Decimal(100)).quantize(CENT, rounding=ROUND_HALF_UP)


def loyalty_discount(amount: Decimal, years: int) -> Decimal:
    percent = min(Decimal(years) * Decimal(2), Decimal(10))
    return apply_percentage(amount, percent)
